use serde_json::{json,Value};use sha2::{Digest,Sha256};use std::fs;
const R:&str="/home/ubuntu/src/zopro-perf-work/g2-joint-ring-census176";
fn read(p:&str)->Value{serde_json::from_slice(&fs::read(p).unwrap()).unwrap()}
fn hash(p:&str)->String{format!("{:x}",Sha256::digest(fs::read(p).unwrap()))}
fn main(){assert!(!std::path::Path::new(&format!("{R}/review.json")).exists());let pins=read(&format!("{R}/pins.json"));for(p,h)in pins.as_object().unwrap(){assert_eq!(hash(p),h.as_str().unwrap());}let plan=read(&format!("{R}/plan.json"));let mut normalized=plan.clone();normalized.as_object_mut().unwrap().entry("environment").or_insert(json!({}));assert_eq!(normalized,read(&format!("{R}/runs/protocol.json")));assert_eq!(read(&format!("{R}/runs/attempt-0.json"))["resume"],false);let mut tests=0;
for s in plan["steps"].as_array().unwrap(){let name=s["name"].as_str().unwrap();let b=format!("{R}/runs/{name}");let e=read(&format!("{b}/exit.json"));assert_eq!(e["returncode"],0);assert_eq!(e["success"],true);for stream in["stdout","stderr"]{assert_eq!(hash(&format!("{b}/{stream}.log")),e[format!("{stream}_sha256")].as_str().unwrap());}let c=read(&format!("{b}/command.json"));assert!(c["argv"].as_array().unwrap().ends_with(s["argv"].as_array().unwrap()));assert_eq!(c["environment"],json!({}));if s["argv"].as_array().unwrap().iter().any(|v|v=="--exact"){let t=read(&format!("{b}/tests.json"));let passed=t["passed_tests"].as_array().unwrap();assert_eq!(passed.len(),1);assert_eq!(passed[0],format!("tests::{name}"));tests+=1;}}
assert_eq!(tests,3);assert_eq!(read(&format!("{R}/runs/result.json"))["status"],"complete");let a=read(&format!("{R}/analysis.json"));let old=read("/home/ubuntu/src/zopro-perf-work/g2-joint-ring-screen176/analysis.json");let u=|v:&Value,k:&str|v[k].as_u64().unwrap();let mut cases=vec![];
for case in a["cases"].as_array().unwrap(){let c=&case["counts"];let previous=old["cases"].as_array().unwrap().iter().find(|v|v["case"]==case["case"]).unwrap();for key in["original_stream","ring_stream"]{let s=&c[key];assert_eq!(u(s,"affine_pairs")+u(s,"projective_mixed_additions")+u(s,"finish_projective_affine_joins"),u(s,"arrivals")-u(s,"first_assignments"));assert_eq!(8*u(s,"full_8lane_groups")+u(s,"scalar_tail_pairs"),u(s,"affine_pairs"));assert_eq!(u(s,"normalization_points"),u(s,"projective_first_assignments"));assert_eq!(u(s,"projective_first_assignments")+u(s,"projective_mixed_additions"),u(s,"queued_points_to_projective"));}
for key in["original_indexed_top","ring_indexed_top","original_merges_and_weighted","ring_merges_axes_and_weighted"]{let s=&c[key];let mut pairs=0;let mut calls=0;let mut lanes=0;let mut tails=0;let mut prefix=0;let mut zero=0;for(m,n)in s["ordinary_pair_count_histogram"].as_object().unwrap(){let m=m.parse::<u64>().unwrap();let n=n.as_u64().unwrap();pairs+=m*n;calls+=n;lanes+=(m/8)*n;tails+=(m%8)*n;prefix+=u64::from(m>=32)*n;zero+=u64::from(m==0)*n;}for(k,v)in[("generic_affine_pairs",pairs),("batch_or_tree_layer_calls",calls),("full_8lane_groups",lanes),("scalar_tail_pairs",tails),("prefix_eligible_m_ge32",prefix),("zero_pair_layers",zero)]{assert_eq!(u(s,k),v);}}
assert_eq!(c["rows"],previous["raw_rows"]);assert_eq!(c["ring_affine_unit_phi_maps"],previous["model"]["ring"]["unit_phi_maps"]);let gate=u(&c["ring_stream"],"affine_pairs")<u(&c["original_stream"],"affine_pairs")&&u(&c["ring_stream"],"projective_mixed_additions")+u(&c["ring_stream"],"finish_projective_affine_joins")<=u(&c["original_stream"],"projective_mixed_additions")+u(&c["original_stream"],"finish_projective_affine_joins");assert_eq!(c["native_correctness_design_permitted"],gate);let affine=|prefix:&str|u(&c[format!("{prefix}_stream")],"affine_pairs")+u(&c[format!("{prefix}_indexed_top")],"generic_affine_pairs")+u(&c[if prefix=="ring"{"ring_merges_axes_and_weighted"}else{"original_merges_and_weighted"}],"generic_affine_pairs");cases.push(json!({"case":case["case"],"total_original_generic_affine_pairs":affine("original"),"total_ring_generic_affine_pairs":affine("ring"),"native_correctness_design_permitted":gate}));}
let out=json!({"passed":true,"review_scope":"source/input pins, six command receipts, exact three new test selections, stream addition/queue conservation and all batch histogram arithmetic, inherited ring phi masks and necessary decision; does not independently replay every tree or curve exception","pins":pins.as_object().unwrap().len(),"commands":6,"new_model_tests":3,"parent_tests_rerun":false,"production_originals_exact":176,"cases":cases,"native_measurement_selected":false,"new_proofs":0,"proof_ledger":30708,"adopted":false,"goal_achieved":false});fs::write(format!("{R}/review.json"),serde_json::to_vec_pretty(&out).unwrap()).unwrap();println!("Review PASS: {}pins/6commands/3newtests; aggregate work conservation, no independent curve replay",pins.as_object().unwrap().len());}
